public void postBuild()
{
    NDXSSRSReportProdTableProdIdentContract contract;
    super();
    contract = this.dataContractObject();

    this.bindInfo().getDialogField(
        contract,
        methodStr(NDXSSRSReportProdTableProdIdentContract, parmProdId))
        .enabled(false);
    this.bindInfo().getDialogField(
        contract,
        methodStr(NDXSSRSReportProdTableProdIdentContract, parmOrderQuantity))
        .enabled(false);
    this.bindInfo().getDialogField(
        contract,
        methodStr(NDXSSRSReportProdTableProdIdentContract, parmProdIdentControlPanelManual))
        .enabled(false);
    this.bindInfo().getDialogField(
        contract,
        methodStr(NDXSSRSReportProdTableProdIdentContract, parmProdIdentManualId))
        .enabled(false);
}
